import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const outDir = join(root, "src", "terminal", "generated");

const SOURCES = [
  ["XTERM_JS", join(root, "node_modules", "@xterm", "xterm", "lib", "xterm.js")],
  ["XTERM_CSS", join(root, "node_modules", "@xterm", "xterm", "css", "xterm.css")],
  ["ADDON_FIT_JS", join(root, "node_modules", "@xterm", "addon-fit", "lib", "addon-fit.js")],
];

const HEADER = `// Generated by scripts/build-terminal-bundle.mjs. Do not edit.
// Payloads are base64 so they can be inlined into the WebView HTML without escaping hazards.

export const GENERATED_AT = ${JSON.stringify(new Date().toISOString())};
`;

const chunks = [HEADER];

for (const [name, path] of SOURCES) {
  const raw = readFileSync(path);
  const encoded = Buffer.from(raw).toString("base64"); // eslint-disable-line no-undef -- Node global
  chunks.push(`\nexport const ${name}_B64 =\n  ${JSON.stringify(encoded)};\n`);
  const kb = (raw.length / 1024).toFixed(1);
  const kbB64 = (encoded.length / 1024).toFixed(1);
  console.log(`  ${name.padEnd(14)} ${kb.padStart(7)} KiB -> ${kbB64.padStart(7)} KiB base64`);
}

mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "assets.ts"), chunks.join(""), "utf8");
console.log(`wrote ${join(outDir, "assets.ts")}`);
